// === Tab: mySketch ===
// Attractor_22.0

let DX = -100 ; let DY = -100 ; let P = 2 ; let PP = sqrt(P) ; let max = 400 ;

let SX ; let SY ; let H ; let X ; let Y ; let C ; 
let I ; let II ; let III ; let A ; let R ; let B ;

function setup(){
	createCanvas(600, 600) ; noSmooth() ; background(0) ; fill(255) ; textSize(20) ;
	SX = -300 ; SY = -300 ; H = 600 ; B = 1 ;
}//setup()

function draw(){
	  for ( I = 0 ; I < 600 ; I++ ){
			X = I*H/600 + SX ; Y = II*H/600 + SY ;
			C = 0 ;
			for ( III = 0 ; III < max ; III++ ){
				R = sqrt(pow(X,2)+pow(Y,2)) ; 
        A = atan(Y/X) ;
        if ( X < 0 ){ A = A+PI ; }  
			  if ( X >= 0 && Y < 0 ){ A = A+(2*PI) ; }
        A = A/P ; R = R*PP ;
        X = R*cos(A) ; Y = R*sin(A) ;
			  Y = Y+DY ; X = X+DX ;
				C = C+1 ;
				if ( R > 3000 ){ III = max ; }
			}//III
			if ( C < max ){ C = 100*C/max ; stroke(125*sin(C)+125,0,0) ; }else{ stroke(0) ; } 
			point(I,II) ;
		}//let II = II+1 ; if ( II >= 600 ){ II = 0 ; } 
	text("*"+B,20,20) ;
}//draw()

function mousePressed(){
	X = H*float((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))))/600 + SX ; 
	Y = H*float((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))/600 + SY ;
	SX = X-(H/4) ; SY = Y-(H/4) ; H = H/2 ; B = B*2 ;
	background(0) ;
}//mousePressed()

